const toggleFavorite = async (productId: string) => {
  const isFavorite = favoriteStore.isFavorite(productId);

  try {
    if (isFavorite) {
      await favoriteService.remove(productId);
      favoriteStore.removeFavorite(productId);
    } else {
      await favoriteService.add(productId);
      favoriteStore.addFavorite(productId);
    }

    // Mettre à jour le compteur de favoris dans le store
    favoriteStore.updateCount(productId, !isFavorite);
  } catch (error) {
    // Afficher un message d'erreur
    Toast.show({
      type: 'error',
      text1: 'Erreur',
      text2: 'Impossible de modifier les favoris',
    });
  }
};
